def variable_type(vector, boolean_type="numeric"):
    """Determine whether a vector contains numeric, categorical, or datetime data.

    This function differs from the pandas typing API in a few ways:

    - Python sequences or object-typed PyData objects are considered numeric if
      all of their entries are numeric.
    - String or mixed-type data are considered categorical even if not
      explicitly represented as a :class:`pandas.api.types.CategoricalDtype`.
    - There is some flexibility about whether numerical encodings can be used
      for either categorical or numeric data, controlled by the `boolean_type`
      parameter.

    Parameters
    ----------
    vector : array-like
        A vector of data.
    boolean_type : {'numeric', 'categorical'}, optional
        How to treat boolean data.

    Returns
    -------
    type : {'numeric', 'categorical', 'datetime'}
        The semantic type of the data.

    """
    vector = pd.Series(vector)

    # Special-case all-na values
    if pd.isnull(vector).all():
        return "numeric"

    # Check for numeric data
    if pd.api.types.is_numeric_dtype(vector):
        if boolean_type == "numeric":
            return "numeric"
        elif vector.isin([0, 1]).all():
            return "boolean"
        else:
            return "numeric"

    # Check for datetime data
    if pd.api.types.is_datetime64_dtype(vector):
        return "datetime"

    # Check for categorical data
    if pd.api.types.is_categorical_dtype(vector):
        return "categorical"

    # Otherwise, check if the data are strings
    if vector.dtype == object:
        # This is a hack to allow StringDtype
        vector = vector.astype(str)
        return "categorical"

    # If we get here, we have a numeric type that pandas doesn't recognize
    if np.isnan(vector).any():
