def _parse_datasets(
    datasets: Iterable[Dataset],
) -> Tuple[
    Dict[Hashable, Variable],
    Dict[Hashable, int],
    Set[Hashable],
    Set[Hashable],
    Dict[Hashable, Variable],
]:
