    def _eval_rewrite_as_sinh(self, arg):
        return S.ImaginaryUnit / sinh(arg + S.ImaginaryUnit * S.Pi /2)

    def _sage_(self):
        import sage.all as sage
        return sage.sech(self.args[0]._sage_())



